-- Built-in food list for searching while logging. Values are rounded approximations from common
-- nutrition tables (home-style recipes vary), stored per 100 g plus one typical serving.
-- Entries keep their own copy of kcal/protein, so editing this list never rewrites past days.
CREATE TABLE foods (
    id               BIGSERIAL PRIMARY KEY,
    category         VARCHAR(20)  NOT NULL,
    name_tr          VARCHAR(100) NOT NULL,
    name_en          VARCHAR(100) NOT NULL,
    kcal_per_100g    NUMERIC(5,1) NOT NULL CHECK (kcal_per_100g BETWEEN 0 AND 900),
    protein_per_100g NUMERIC(4,1) NOT NULL CHECK (protein_per_100g BETWEEN 0 AND 100),
    serving_g        NUMERIC(5,1) NOT NULL CHECK (serving_g > 0),
    serving_tr       VARCHAR(40)  NOT NULL,
    serving_en       VARCHAR(40)  NOT NULL
);

